<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <title>Conway's Game of Life</title>
    <style>
        :root { --bg: #121212; --grid-bg: #000; }

        body { 
            background-color: var(--bg); color: #e0e0e0; font-family: sans-serif; 
            display: flex; justify-content: center; align-items: center; min-height: 100vh; margin: 0; padding: 20px; box-sizing: border-box;
        }

        .game-wrapper { text-align: center; width: 100%; max-width: 640px; display: flex; flex-direction: column; gap: 20px;}

        canvas#life { 
            background-color: var(--grid-bg); border: 4px solid #333; image-rendering: pixelated;
            /* Minimum visual size constraint */
            width: 100%; max-width: 500px; aspect-ratio: 1 / 1; min-width: 400px; min-height: 400px; 
        }

        .controls { display: flex; justify-content: center; gap: 12px; flex-wrap: wrap;}

        button { 
            padding: 10px 20px; border: none; border-radius: 6px; font-weight: bold; cursor: pointer; color: #fff; transition: all 0.2s ease; box-shadow: 0 4px 6px rgba(0,0,0,0.3);
        }

        button:hover { transform: translateY(-2px); filter: brightness(1.1);}
        button:active { transform: translateY(1px); opacity: 0.9; }

        #step { background-color: #3b82f6; } /* Blue */
        #play { background-color: #10b981; } /* Green */
        #random { background-color: #8b5cf6; } /* Purple */
        #clear { background-color: #ef4444; } /* Red */

    </style>
</head>
<body>

<div class="game-wrapper">
    <canvas id="life"></canvas>
    <div class="controls">
        <button id="step">Step</button>
        <button id="play">Play/Pause</button>
        <button id="random">Randomize</button>
        <button id="clear">Clear All</button>
    </div>
</div>

<script>
(function() {
    // Grid Dimensions (>= 40)
    const W = 50; 
    const H = 50; 

    let grid, nextGrid;

    function createGrid(rows, cols) {
        return Array.from({ length: rows }, () => Array(cols).fill(0));
    }

    // Initialize Grids (Double Buffering for Simultaneous Update)
    grid = createGrid(H, W);
    nextGrid = createGrid(H, W);

    // Canvas Setup
    const canvas = document.getElementById('life');
    const ctx = canvas.getContext('2d', { alpha: false }); 

    let drawW = 0; 
    let drawH = 0;

    function resizeCanvas() {
        // Get rendered CSS size (or default if hidden)
        const rect = canvas.getBoundingClientRect();
        const width = Math.max(400, rect.width);
        const height = Math.max(400, rect.height);

        drawW = Math.round(width);
        drawH = Math.round(height);

        // Set intrinsic resolution to match CSS for sharpness (1:1 mapping)
        if(canvas.width !== drawW || canvas.height !== drawH) {
            canvas.width = drawW;
            canvas.height = drawH;
        }
    }

    window.addEventListener('resize', resizeCanvas);

    // --- SIMULATION LOGIC ---

    function countNeighbors(x, y) {
        let sum = 0;
        for (let dy = -1; dy <= 1; dy++) {
            for (let dx = -1; dx <= 1; dx++) {
                if (dx === 0 && dy === 0) continue;

                const nx = x + dx;
                const ny = y + dy;

                // Edges are dead: Check bounds. If out, contributes 0 to sum.
                if (nx >= 0 && nx < W && ny >= 0 && ny < H) {
                    sum += grid[ny][nx];
                }
            }
        }
        return sum;
    }

    function step() {
        // Compute next state simultaneously using double buffer logic
        for (let y = 0; y < H; y++) {
            for (let x = 0; x < W; x++) {
                const neighbors = countNeighbors(x, y);
                const cellVal = grid[y][x];

                if (cellVal === 1) {
                    // Live: Survives with 2 or 3 live neighbours.
                    nextGrid[y][x] = (neighbors === 2 || neighbors === 3) ? 1 : 0;
                } else {
                    // Dead: Born with exactly 3 live neighbours.
                    nextGrid[y][x] = (neighbors === 3) ? 1 : 0;
                }
            }
        }

        // Swap buffers so grid becomes the newly computed state for future steps/draws
        [grid, nextGrid] = [nextGrid, grid];

        draw();
    }

    function clearAll() {
        for(let y=0; y<H; y++) {
            for(let x=0; x<W; x++) {
                grid[y][x] = 0;
            }
        }
        // Clear nextGrid implicitly handled by step swap or just draw to reflect current state.
        draw();
    }

    function randomSeed() {
        for(let y=0; y<H; y++) {
            for(let x=0; x<W; x++) {
                grid[y][x] = Math.random() < 0.25 ? 1 : 0; // ~25% alive
            }
        }
        draw();
    }

    function draw() {
        ctx.fillStyle = '#121212'; 
        ctx.fillRect(0, 0, drawW, drawH);

        const cellSizeX = drawW / W;
        const cellSizeY = drawH / H;

        for (let y = 0; y < H; y++) {
            for (let x = 0; x < W; x++) {
                if (grid[y][x] === 1) {
                    ctx.fillStyle = '#4ade80'; 
                    // Draw exact rectangle based on index and size. Using Math.ceil to avoid gaps due to float rounding?
                    // But since drawW/W is computed from integers, it should be consistent.
                    // Adding +0.5 ensures coverage of sub-pixel anti-aliasing artifacts sometimes seen.
                    ctx.fillRect(x * cellSizeX, y * cellSizeY, Math.ceil(cellSizeX) - 1, Math.ceil(cellSizeY)); 
                }
            }
        }
    }

    // --- API EXPOSURE (window.life) ---

    window.life = {
        get w() { return W; },
        get h() { return H; },

        get: function(x, y) {
            if (x < 0 || x >= W || y < 0 || y >= H) return 0;
            return grid[y][x];
        },

        set: function(x, y, v) {
            // "set cell (x,y) alive (truthy) or dead" -> Returns nothing. 
            if (x < 0 || x >= W || y < 0 || y >= H) return;
            grid[y][x] = v ? 1 : 0;
        },

        step: function() {
            // advance exactly one generation (and redraw)
            step(); 
        },

        clear: function() {
            clearAll();
        }
    };

    // --- INTERACTION & BUTTONS ---

    let isMouseDown = false;

    function handleMouse(e) {
        if (!isMouseDown) return;

        const rect = canvas.getBoundingClientRect();
        const xRaw = e.clientX - rect.left;
        const yRaw = e.clientY - rect.top;

        // Calculate cell coordinates based on rendered size (CSS dimensions mapped to grid indices)
        const cx = Math.floor(xRaw / (drawW / W));
        const cy = Math.floor(yRaw / (drawH / H));

        if (cx >= 0 && cx < W && cy >= 0 && cy < H) {
            // Toggle cell state visually immediately
            grid[cy][cx] = !grid[cy][cx]; 
            draw();
        }
    }

    function updatePlayButton() {
        const btn = document.getElementById('play');
        if(autoRunId) {
            clearInterval(autoRunId);
            autoRunId = null;
            btn.textContent = 'Play';
        } else {
             // Run one step immediately before starting loop? Or start loop only? 
             autoRunId = setInterval(step, 80);
        }
    }

    let autoRunId = null;

    document.getElementById('step').addEventListener('click', step);
    document.getElementById('play').addEventListener('click', updatePlayButton);
    document.getElementById('random').addEventListener('click', randomSeed);
    document.getElementById('clear').addEventListener('click', clearAll);

    // Mouse interaction listeners: use global scope for drag out of bounds support (optional but nice)
    canvas.addEventListener('mousedown', () => isMouseDown = true);

    window.addEventListener('mouseup', () => isMouseDown = false);
    window.addEventListener('mousemove', handleMouse);

    // --- INITIALIZATION ---

    resizeCanvas();
    draw(); 

})();
</script>
</body>
</html>
